    type(DeformationMechanism) function get_deformation_mechanism(key) result(mechanism)
        character(*), intent(in) :: key

        select case(key)
            case('fcc12')
                mechanism = DeformationMechanism(SLIP_SYSTEMS_111, INITIAL_BASIS_SYSTEMS_FCC, INITIAL_INVERSE_BASIS_FCC)
            case('bcc24')
                mechanism = DeformationMechanism(SLIP_SYSTEMS_110_112, INITIAL_BASIS_SYSTEMS_BCC, INITIAL_INVERSE_BASIS_BCC)
            case('bcc48')
                mechanism = DeformationMechanism([SLIP_SYSTEMS_110_112, SLIP_SYSTEMS_123], INITIAL_BASIS_SYSTEMS_BCC, INITIAL_INVERSE_BASIS_BCC)
            case default
                call log_error('slip_systems', 'get_deformation_mechanism', ERR_VAL, 'Invalid slip system identifier')
        end select
    end function

